def _parse_date(text: str) -> datetime | None:
    """Parse FMP's cover-page date renderings ("Dec. 31,  2025", ISO).

    Returns None rather than raising: a missing period-end is a degraded but
    workable row (fiscal year still resolves from the payload's own ``year``),
    whereas a raised error would drop an otherwise-good filing.
    """
    cleaned = _clean(text)
    iso = _ISO_DATE_RX.search(cleaned)
    if iso is not None:
        try:
            return datetime(int(iso.group(1)), int(iso.group(2)), int(iso.group(3)))
        except ValueError:
            return None
    m = _DATE_RX.search(cleaned)
    if m is None:
        return None
    month = _MONTHS.get(m.group(1).lower()[:4]) or _MONTHS.get(m.group(1).lower()[:3])
    if month is None:
        return None
    try:
        return datetime(int(m.group(3)), month, int(m.group(2)))
    except ValueError:
        return None

def _digest(self) -> Self:
        if _sha(_canonical(self.canonical_footnote).encode()) != self.footnote_sha256:
            raise ValueError("footnote digest does not match canonical payload")
        return self

def _now_iso() -> str:
    """Naive-UTC ISO timestamp (repo convention — never store an aware stamp)."""
    return now_naive_utc().isoformat(timespec="seconds")

def _table_exists(conn: sqlite3.Connection, name: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (name,)
    ).fetchone()
    return row is not None

def _sha256(cls, value: str) -> str:
        normalized = value.lower()
        if not re.fullmatch(r"[0-9a-f]{64}", normalized):
            raise ValueError("raw_sha256 must be a lowercase SHA-256 digest")
        return normalized

def _parse_datetime(value: object) -> datetime:
